// Which parts of the opening day (07:00-21:00) are still free?
// booked: ranges [start, end] in minutes, in ANY order, never overlapping.
export const OPEN = 420;
export const CLOSE = 1260;

export type TimeRange = readonly number[];

// readonly TimeRange[]: we only read the caller's list (it may be shared with the page).
export function freeGaps(booked: readonly TimeRange[]): TimeRange[] {
  const gaps: TimeRange[] = [];
  let cursor = OPEN;
  for (const [start = 0, end = 0] of booked.toSorted((a, b) => (a[0] ?? 0) - (b[0] ?? 0))) {   // a sorted COPY
    if (start > cursor) gaps.push([cursor, start]);
    cursor = Math.max(cursor, end);
  }
  if (cursor < CLOSE) gaps.push([cursor, CLOSE]);
  return gaps;
}

